'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),$=s=>document.querySelector(s);
const W=1200,H=800,keys=new Set(),colors=['#65e9ff','#a4ed83','#ffbe7e'],names=['יוגו','אמליה','פרסדל'],icons=['🌀','🌿','⚔️'];
const bg=new Image();bg.src='forest.png';
let heroes=[],enemies=[],particles=[],shots=[],selected=0,mode='intro',paused=false,wave=0,timer=0,last=0,transition=0,mouse={x:600,y:400},tutorial={move:0,switched:false,attack:false,special:false},toastTime=0;
function reset(){heroes=names.map((name,i)=>({name,x:550+i*65,y:440+(i===1?60:0),hp:100,cd:0,attackCd:0,inv:0,face:0}));enemies=[];particles=[];shots=[];selected=0;wave=0;transition=0;tutorial={move:0,switched:false,attack:false,special:false};updateUI();}
function resize(){const r=canvas.getBoundingClientRect();canvas.width=r.width*devicePixelRatio;canvas.height=r.height*devicePixelRatio;}
new ResizeObserver(resize).observe(canvas);
function say(s){$('#toast').textContent=s;$('#toast').classList.add('show');toastTime=3;}
function effect(x,y,color,r=50){particles.push({x,y,color,r,life:.5,max:.5});}
function switchHero(i){if(!heroes[i]||heroes[i].hp<=0)return;if(i!==selected){selected=i;tutorial.switched=true;effect(heroes[i].x,heroes[i].y,colors[i],55);updateUI();}}
function updateUI(){document.querySelectorAll('.hero').forEach((b,i)=>{b.classList.toggle('active',selected===i);b.setAttribute('aria-pressed',String(selected===i));b.querySelector('.health i').style.width=Math.max(0,heroes[i]?.hp??100)+'%';b.style.opacity=heroes[i]?.hp<=0?.4:1;});$('#specialName').textContent=['קפיצת שער','שורשים','סחרור חרב'][selected];}
function nearest(h){return enemies.filter(e=>e.hp>0).sort((a,b)=>dist(h,a)-dist(h,b))[0];}
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y);}
function damage(e,n){e.hp-=n;e.flash=.14;effect(e.x,e.y,'#ffe6a2',22);if(e.hp<=0&&!e.dead){e.dead=true;effect(e.x,e.y,'#c9f69e',60);}}
function attack(i=selected){if(!['training','battle'].includes(mode)||paused)return;const h=heroes[i];if(h.hp<=0||h.attackCd>0)return;h.attackCd=i===2?.48:.6;const e=nearest(h);let a=e?Math.atan2(e.y-h.y,e.x-h.x):h.face;h.face=a;if(i===2){effect(h.x+Math.cos(a)*30,h.y+Math.sin(a)*30,colors[i],80);enemies.forEach(e=>{if(dist(h,e)<115)damage(e,30);});}else{shots.push({x:h.x,y:h.y,vx:Math.cos(a)*460,vy:Math.sin(a)*460,life:.9,color:colors[i],dmg:i===0?19:16});}if(i===selected)tutorial.attack=true;}
function special(){if(!['training','battle'].includes(mode)||paused)return;const h=heroes[selected];if(h.cd>0||h.hp<=0)return;h.cd=selected===0?5:7;tutorial.special=true;if(selected===0){effect(h.x,h.y,colors[0],65);let e=nearest(h),a=e?Math.atan2(e.y-h.y,e.x-h.x):h.face;h.x+=Math.cos(a)*160;h.y+=Math.sin(a)*160;bound(h);h.inv=.8;effect(h.x,h.y,colors[0],95);enemies.forEach(e=>{if(dist(h,e)<125)damage(e,38);});}else if(selected===1){effect(h.x,h.y,colors[1],215);enemies.forEach(e=>{if(dist(h,e)<240){e.root=3;damage(e,24);}});}else{effect(h.x,h.y,colors[2],170);enemies.forEach(e=>{if(dist(h,e)<185)damage(e,65);});}}
function dodge(){if(!['training','battle'].includes(mode)||paused)return;const h=heroes[selected];if(h.inv>0)return;h.x+=Math.cos(h.face)*95;h.y+=Math.sin(h.face)*95;bound(h);h.inv=.6;effect(h.x,h.y,'#fff',42);}
function bound(h){h.x=Math.max(135,Math.min(W-135,h.x));h.y=Math.max(190,Math.min(H-115,h.y));}
function showPanel(title,text,label,callback){$('#overlay').hidden=false;$('#overlay .intro').innerHTML='<div class="eyebrow">שומרי היער</div><h1>'+title+'</h1><p>'+text+'</p><button class="primary" id="continue">'+label+' ←</button>';$('#continue').onclick=callback;$('#continue').focus();}
const initialIntro=$('#overlay .intro').innerHTML;
function startTraining(){reset();mode='training';paused=false;$('#overlay').hidden=true;enemies=[{x:790,y:375,hp:999,max:999,r:25,dummy:true,root:0,flash:0}];$('#modeLabel').textContent='תרגול חופשי';$('#objective').textContent='זוזי עם החצים כדי להתחיל';canvas.focus();}
function startBattle(){mode='battle';paused=false;$('#overlay').hidden=true;enemies=[];heroes.forEach(h=>h.hp=100);nextWave();canvas.focus();}
function nextWave(){wave++;if(wave>3){mode='win';showPanel('הכפר בטוח!','החבורה הצליחה להגן על היער.<br>כל דמות הביאה כוח אחר — וביחד ניצחתן.','לשחק שוב',()=>{reset();startBattle();});return;}heroes.forEach(h=>{if(h.hp>0)h.hp=Math.min(100,h.hp+30);else h.hp=45;});enemies=Array.from({length:wave===3?3:wave+2},(_,i)=>({x:220+i*240,y:i%2?245:610,hp:wave===3&&i===0?440:60+wave*15,max:wave===3&&i===0?440:60+wave*15,r:wave===3&&i===0?43:24,boss:wave===3&&i===0,root:0,flash:0,cd:1,wind:0}));$('#modeLabel').textContent='הגנה על הכפר · '+wave+' / 3';$('#objective').textContent=wave===3?'הביסו את שומר הסבך':'הגנו על קרחת היער';say(wave===3?'שומר הסבך הגיע! התחמקי מהעיגול האדום':'החבורה איתך. אפשר להחליף דמות בכל רגע');updateUI();}
function tick(dt){timer+=dt;if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('#toast').classList.remove('show');}if(paused||!['training','battle'].includes(mode))return;const h=heroes[selected];let dx=(keys.has('ArrowRight')||keys.has('KeyD')?1:0)-(keys.has('ArrowLeft')||keys.has('KeyA')?1:0),dy=(keys.has('ArrowDown')||keys.has('KeyS')?1:0)-(keys.has('ArrowUp')||keys.has('KeyW')?1:0);if(dx||dy){const n=Math.hypot(dx,dy);h.x+=dx/n*235*dt;h.y+=dy/n*235*dt;h.face=Math.atan2(dy,dx);bound(h);tutorial.move+=dt;}if(keys.has('KeyJ'))attack();heroes.forEach((a,i)=>{a.cd=Math.max(0,a.cd-dt);a.attackCd=Math.max(0,a.attackCd-dt);a.inv=Math.max(0,a.inv-dt);if(i===selected||a.hp<=0)return;const e=mode==='battle'?nearest(a):null;let tx=h.x+(i===0?-70:70),ty=h.y+50;if(e&&dist(e,h)<370){const angle=Math.atan2(a.y-e.y,a.x-e.x),reach=i===2?70:210;tx=e.x+Math.cos(angle)*reach;ty=e.y+Math.sin(angle)*reach;if(dist(a,e)<(i===2?110:350))attack(i);}const len=Math.hypot(tx-a.x,ty-a.y);if(len>12){a.x+=(tx-a.x)/len*Math.min(len,180*dt);a.y+=(ty-a.y)/len*Math.min(len,180*dt);bound(a);}});
shots.forEach(s=>{s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;for(const e of enemies){if(e.hp>0&&dist(s,e)<e.r+10){damage(e,s.dmg);s.life=0;break;}}});shots=shots.filter(s=>s.life>0);
for(const e of enemies){e.flash=Math.max(0,e.flash-dt);e.root=Math.max(0,e.root-dt);if(e.dummy){e.hp=999;continue;}if(e.hp<=0)continue;let target=heroes.filter(a=>a.hp>0).sort((a,b)=>dist(e,a)-dist(e,b))[0];if(!target)continue;e.cd-=dt;if(e.wind>0){e.wind-=dt;if(e.wind<=0){heroes.forEach(a=>{if(a.hp>0&&dist(e,a)<(e.boss?140:60)&&a.inv<=0){a.hp-=e.boss?25:9;a.inv=.45;effect(a.x,a.y,'#ef8c7f',50);}});e.cd=e.boss?2.4:1.1;}}else if(e.root<=0){let d=dist(e,target);if(d>(e.boss?110:43)){e.x+=(target.x-e.x)/d*(e.boss?72:90)*dt;e.y+=(target.y-e.y)/d*(e.boss?72:90)*dt;}else if(e.cd<=0)e.wind=e.boss?1:.45;}}
particles.forEach(p=>p.life-=dt);particles=particles.filter(p=>p.life>0);enemies=enemies.filter(e=>e.hp>0);
if(h.hp<=0){const alive=heroes.findIndex(a=>a.hp>0);if(alive>=0){selected=alive;say('הדמות נחה. ממשיכים עם החבורה!');}else{mode='lost';showPanel('ננסה שוב, ביחד?','החבורה צריכה מנוחה קטנה.<br>כדאי להחליף דמויות ולהתחמק מהמתקפות האדומות.','לנסות שוב',()=>{reset();startBattle();});}}
if(mode==='training'){const done=[tutorial.move>.6,tutorial.switched,tutorial.attack,tutorial.special],labels=['זוזי עם החצים או WASD','החליפי דמות עם 1, 2 או 3','לחצי J ותקפי את בובת האימון','נסי יכולת מיוחדת עם E'];let ix=done.findIndex(x=>!x);$('#objective').textContent=ix<0?'מוכנה להרפתקה!':labels[ix];$('#progress').textContent=done.map((x,i)=>(x?'✓':'○')+' '+['תנועה','החלפה','תקיפה','יכולת'][i]).join('   ·   ');if(ix<0){mode='ready';showPanel('את מוכנה להרפתקה!','זזת, החלפת דמות והפעלת את הכוחות שלה.<br>בקרב החברים יעזרו לך אוטומטית.<br>רווח להתחמקות · P לעצירה','יוצאים להגן על הכפר',startBattle);}}
if(mode==='battle'){$('#progress').textContent=enemies.length+' אויבים בקרחת היער';if(enemies.length===0){transition+=dt;if(transition>1.6){transition=0;nextWave();}}}updateUI();$('#cooldown').style.width=(1-h.cd/(selected===0?5:7))*100+'%';const boss=enemies.find(e=>e.boss);$('#bossHud').hidden=!boss;if(boss)$('#bossHud i').style.width=boss.hp/boss.max*100+'%';}
function circle(x,y,r,fill,stroke){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=3;ctx.stroke();}}
function draw(){const scale=Math.max(canvas.width/W,canvas.height/H),vw=canvas.width/scale,vh=canvas.height/scale;const focus=heroes[selected]||{x:600,y:400};const ox=Math.max(0,Math.min(W-vw,focus.x-vw/2)),oy=Math.max(0,Math.min(H-vh,focus.y-vh/2));ctx.setTransform(scale,0,0,scale,-ox*scale,-oy*scale);ctx.clearRect(0,0,W,H);if(bg.complete&&bg.naturalWidth)ctx.drawImage(bg,0,0,W,H);else{ctx.fillStyle='#315f49';ctx.fillRect(0,0,W,H);}ctx.fillStyle='#052c2722';ctx.fillRect(0,0,W,H);for(let i=0;i<20;i++){const x=150+(i*137)%950,y=180+(i*83)%510;circle(x+Math.sin(timer*.5+i)*15,y+Math.cos(timer*.7+i)*13,2,'#e9ffd580');}
for(const p of particles){ctx.globalAlpha=p.life/p.max;circle(p.x,p.y,p.r*(1-p.life/p.max)+12,null,p.color);ctx.globalAlpha=1;}
for(const e of enemies){if(e.wind>0){circle(e.x,e.y,e.boss?140:60,'#ff4d442f','#ff8578');}circle(e.x,e.y+20,e.r,'#071e274d');circle(e.x,e.y,e.r,e.flash>0?'#fff4c6':e.dummy?'#7c6850':e.boss?'#485331':'#746146',e.root>0?'#acf680':'#d0b47a');ctx.font=(e.boss?51:32)+'px Apple Color Emoji, Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(e.dummy?'🎯':e.boss?'👹':'🐗',e.x,e.y-1);if(!e.dummy){ctx.fillStyle='#162d27';ctx.fillRect(e.x-25,e.y-e.r-14,50,5);ctx.fillStyle='#efb482';ctx.fillRect(e.x-25,e.y-e.r-14,50*Math.max(0,e.hp/e.max),5);}else{ctx.font='15px Arial';ctx.fillStyle='#fff5cd';ctx.fillText('בובת אימון',e.x,e.y-45);}}
heroes.forEach((h,i)=>{if(h.hp<=0)return;const bob=Math.sin(timer*4+i)*2;circle(h.x,h.y+20,25,'#061f305e');if(i===selected){circle(h.x,h.y+7,34,'#6fe9e718',colors[i]);ctx.fillStyle=colors[i];ctx.beginPath();ctx.moveTo(h.x,h.y-48);ctx.lineTo(h.x-7,h.y-59);ctx.lineTo(h.x+7,h.y-59);ctx.fill();}ctx.globalAlpha=h.inv>0?.65:1;circle(h.x,h.y+bob,24,['#164b69','#345f3a','#885126'][i],colors[i]);ctx.font='30px Apple Color Emoji, Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(icons[i],h.x,h.y+bob);ctx.globalAlpha=1;ctx.font='bold 16px Arial';ctx.lineWidth=4;ctx.strokeStyle='#0b262d';ctx.strokeText(h.name,h.x,h.y+48);ctx.fillStyle='#fff6dc';ctx.fillText(h.name,h.x,h.y+48);});
for(const s of shots){circle(s.x,s.y,7,s.color);circle(s.x-s.vx*.018,s.y-s.vy*.018,4,s.color+'88');}}
function frame(t){const dt=Math.min((t-last)/1000||0,.035);last=t;tick(dt);draw();requestAnimationFrame(frame);}
function pauseGame(){if(!['training','battle'].includes(mode))return;paused=!paused;$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',paused?'המשך':'עצירה');say(paused?'המשחק בהפסקה · P להמשך':'ממשיכים!');}
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;if(['Digit1','Digit2','Digit3'].includes(e.code))switchHero(Number(e.code.slice(-1))-1);if(e.code==='KeyJ')attack();if(e.code==='KeyE')special();if(e.code==='Space')dodge();if(e.code==='KeyP'||e.code==='Escape')pauseGame();});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();if(!paused&&['battle','training'].includes(mode))pauseGame();});document.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>switchHero(Number(b.dataset.hero)));document.querySelectorAll('[data-move]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.move);};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.move);});$('#attack').onclick=()=>attack();$('#special').onclick=special;$('#dodge').onclick=dodge;$('#pause').onclick=pauseGame;$('#start').onclick=startTraining;$('#help').onclick=()=>{if(mode==='intro')return;const wasPaused=paused;paused=true;showPanel('איך משחקים?','חצים או WASD — תנועה חופשית<br>J — תקיפה לעבר האויב הקרוב<br>E — יכולת מיוחדת · רווח — התחמקות<br>1 / 2 / 3 — החלפת דמות<br>P — עצירה והמשך<br><br>אפשר גם ללחוץ על הדמויות ועל כפתורי הפעולות.','חזרה למשחק',()=>{$('#overlay').hidden=true;paused=wasPaused;canvas.focus();});};
reset();requestAnimationFrame(frame);
window.gameState=()=>({mode,paused,selected,heroes:heroes.map(h=>({name:h.name,hp:h.hp,x:h.x,y:h.y})),enemies:enemies.length,wave,tutorial:{...tutorial}});
if(document.modelContext?.registerTool){for(const tool of [{name:'read_game_state',description:'Read the current game phase, selected hero and party health.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>window.gameState()},{name:'select_hero',description:'Select the controlled party hero, numbered 1 through 3.',inputSchema:{type:'object',properties:{hero:{type:'integer',minimum:1,maximum:3}},required:['hero'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!Number.isInteger(input.hero)||input.hero<1||input.hero>3)throw Error('Hero must be 1, 2 or 3');switchHero(input.hero-1);return window.gameState();}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}
